// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function testFuzz_property(address actor, address to_, uint256 loanID) public {
        // The lender of any loan defaults to address(0) in a fresh contract.
        // Any actor that is NOT the lender (not address(0)) must be rejected.
        vm.assume(actor != address(0));

        vm.prank(actor);
        bool ok;
        try c.approveTransfer(to_, loanID) {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: a non-lender's approveTransfer call always reverts.
        assertTrue(!ok);
    }
}
